+package slices
+
+// Batch divides items into batches of specified size.
+func Batch[T any](items []T, batchSize int) [][]T {
+	if batchSize <= 0 {
+		return nil
+	}
+
+	n := len(items)
+	batches := make([][]T, 0, (n+batchSize-1)/batchSize)
+
+	for i := 0; i < n; i += batchSize {
+		end := min(i+batchSize, n)
+		batches = append(batches, items[i:end])
+	}
+
+	return batches
+}

