+// HTTPClient implements Client against a running IAM API.
+type HTTPClient struct {
+	baseURL string // e.g. "https://iam.sitooapis.com/v1"
+	hc      *http.Client
+}
+
+func NewHTTPClient(baseURL string, hc *http.Client) *HTTPClient {
+	if hc == nil {
+		hc = http.DefaultClient
+	}
+	return &HTTPClient{baseURL: baseURL, hc: hc}
+}
+
+func (c *HTTPClient) ListUserAssignments(
+	ctx context.Context,
+	auth string,
+	in ListUserAssignmentsInput,
+) ([]Assignment, error) {
+	q := url.Values{}
+	for _, u := range in.UserIDs {
+		q.Add("user_ids[]", u)
+	}
+	q.Set("environment", string(in.Environment))
+	if in.AccountID != nil {
+		q.Set("account_id", strconv.FormatInt(*in.AccountID, 10))
+	}
+	if in.SiteID != nil {
+		q.Set("site_id", strconv.FormatInt(*in.SiteID, 10))
+	}
+	if in.StoreID != nil {
+		q.Set("store_id", strconv.FormatInt(*in.StoreID, 10))
+	}
+
+	resp, err := c.do(ctx, http.MethodGet, "/user-role-assignments?"+q.Encode(), auth, nil)
+	if err != nil {
+		return nil, err
+	}
+	defer func() { _ = resp.Body.Close() }()
+
+	if err := checkStatus(resp); err != nil {
+		return nil, err
+	}
+
+	var body wireListUserAssignmentsResponse
+	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError, "iam response decode failed")
+	}
+	out := make([]Assignment, 0)
+	for _, group := range body.Items {
+		for _, a := range group.Assignments {
+			out = append(out, a.toAssignment())
+		}
+	}
+	return out, nil
+}
