+) ([]Assignment, error) {
+	body := upsertAssignmentBySlugBody{
+		UserID:      in.UserID,
+		Environment: string(in.Environment),
+		AccountID:   in.AccountID,
+		SiteID:      in.SiteID,
+		StoreIDs:    in.StoreIDs,
+		RoleSlug:    in.RoleSlug,
+	}
+	raw, err := json.Marshal(body)
+	if err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"iam request marshal failed")
+	}
+	resp, err := c.do(ctx, http.MethodPut, "/role-assignment-by-slug", auth, bytes.NewReader(raw))
+	if err != nil {
+		return nil, err
+	}
+	defer func() { _ = resp.Body.Close() }()
+	if err := checkStatus(resp); err != nil {
+		return nil, err
+	}
+	if resp.StatusCode == http.StatusNoContent {
+		return nil, nil
+	}
+	var decoded upsertAssignmentBySlugResponse
+	if err := json.NewDecoder(resp.Body).Decode(&decoded); err != nil {
+		return nil, errors.Wrap(err, errors.CodeInternalServerError,
+			"iam response decode failed")
+	}
+	out := make([]Assignment, 0, len(decoded.Assignments))
+	for _, w := range decoded.Assignments {
+		out = append(out, w.toAssignment())
+	}
+	return out, nil
+}
