+	if in.Sort != nil {
+		q.Set("sort", string(*in.Sort))
+	}
+	if in.Num != nil {
+		q.Set("num", strconv.FormatInt(*in.Num, 10))
+	}
+	if in.Next != nil {
+		q.Set("next", *in.Next)
+	}
+
+	resp, err := c.do(ctx, http.MethodGet, "/roles?"+q.Encode(), auth, nil)
+	if err != nil {
+		return nil, err
+	}
+	defer func() { _ = resp.Body.Close() }()
+
+	if err := checkStatus(resp); err != nil {
+		return nil, err
+	}
+
+	var body wireListRolesResponseEnvelope
+	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
