+package iam
+
+import (
+	"context"
+	"strconv"
+	"sync"
+
+	"github.com/google/uuid"
+)
+
+// MockClient is an in-memory IAM Client for tests + local development.
+//
+// It is keyed by user_id and stores Assignments authored by
+// UpsertAssignmentBySlug (or SeedLegacy). Filters on SiteID/AccountID/StoreID
+// match when the assignment's corresponding scope slice contains the filter
+// value (or always when filter is nil).
+type MockClient struct {
+	mu          sync.Mutex
+	assignments map[string][]Assignment // user_id -> [assignments]
+	roles       []Role
+}
+
+func NewMockClient() *MockClient {
+	return &MockClient{
+		assignments: make(map[string][]Assignment),
+	}
+}
+
+// SeedRole appends a Role to the mock's role store. Used in tests to pre-populate
+// roles for GetRoles calls.
+func (m *MockClient) SeedRole(r Role) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	m.roles = append(m.roles, r)
+}
+
+// ListRoles returns roles from the in-memory store, filtered by Environment and
+// optionally by Slugs. Pagination is driven by a decimal offset cursor in Next.
+func (m *MockClient) ListRoles(
+	_ context.Context,
+	_ string,
+	in GetRolesInput,
+) (*ListRolesResponseEnvelope, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	slugSet := make(map[string]struct{}, len(in.Slugs))
+	for _, s := range in.Slugs {
+		slugSet[s] = struct{}{}
+	}
+
+	var filtered []Role
+	for _, r := range m.roles {
+		if r.Environment != in.Environment {
+			continue
+		}
+		if len(slugSet) > 0 {
+			if _, ok := slugSet[r.Slug]; !ok {
+				continue
+			}
+		}
+		filtered = append(filtered, r)
+	}
+
+	var offset int64
+	if in.Next != nil && *in.Next != "" {
+		offset, _ = strconv.ParseInt(*in.Next, 10, 64)
+	}
+	if offset > int64(len(filtered)) {
+		offset = int64(len(filtered))
+	}
+	page := filtered[offset:]
+
+	var nextCursor string
+	if in.Num != nil && *in.Num < int64(len(page)) {
+		page = page[:*in.Num]
+		nextCursor = strconv.FormatInt(offset+*in.Num, 10)
+	}
+
+	return &ListRolesResponseEnvelope{Items: page, Next: nextCursor}, nil
+}
+
+func (m *MockClient) ListUserAssignments(
+	_ context.Context,
+	_ string,
+	in ListUserAssignmentsInput,
+) ([]Assignment, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	out := make([]Assignment, 0)
+	for _, uid := range in.UserIDs {
+		for _, a := range m.assignments[uid] {
+			if !matchScope(a, in) {
+				continue
+			}
+			out = append(out, a)
+		}
+	}
+	return out, nil
+}
+
+// SeedLegacy injects a synthetic legacy-source assignment. Used in tests
+// to verify read-merge precedence.
+func (m *MockClient) SeedLegacy(a Assignment) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	a.Source = SourceLegacy
+	a.AssignmentID = ""
+	m.assignments[a.UserID] = append(m.assignments[a.UserID], a)
+}
+
+// AllAssignments returns every assignment currently held by the mock.
+// Used by tests to assert whether IAM was (or was not) called.
+func (m *MockClient) AllAssignments() []Assignment {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	var out []Assignment
+	for _, group := range m.assignments {
+		out = append(out, group...)
+	}
+	return out
+}
+
+func (m *MockClient) UpsertAssignmentBySlug(
+	_ context.Context,
+	_ string,
+	in UpsertAssignmentBySlugInput,
+) ([]Assignment, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+
+	m.removeAtSiteLocked(in.UserID, in.AccountID, in.SiteID)
+
+	if in.RoleSlug == "" {
+		return nil, nil
+	}
+
+	a := Assignment{
+		Source:       SourceIAM,
+		AssignmentID: uuid.NewString(),
+		UserID:       in.UserID,
+		Environment:  in.Environment,
+		AccountIDs:   []int64{in.AccountID},
+		SiteIDs:      []int64{in.SiteID},
+		StoreIDs:     append([]int64(nil), in.StoreIDs...),
+		RoleSlug:     in.RoleSlug,
+	}
+	m.assignments[in.UserID] = append(m.assignments[in.UserID], a)
+	return []Assignment{a}, nil
+}
+
+// removeAtSiteLocked drops all assignments for the user at (account, site).
+// Caller must hold m.mu.
+func (m *MockClient) removeAtSiteLocked(user string, account, site int64) {
+	list := m.assignments[user]
+	if list == nil {
+		return
+	}
+	kept := list[:0]
+	for _, a := range list {
+		if !contains(a.AccountIDs, account) || !contains(a.SiteIDs, site) {
+			kept = append(kept, a)
+		}
+	}
+	m.assignments[user] = kept
+}
+
+func matchScope(a Assignment, in ListUserAssignmentsInput) bool {
+	if in.AccountID != nil && !contains(a.AccountIDs, *in.AccountID) {
+		return false
+	}
+	if in.SiteID != nil && !contains(a.SiteIDs, *in.SiteID) {
+		return false
+	}
+	if in.StoreID != nil && !contains(a.StoreIDs, *in.StoreID) {
+		return false
+	}
+	return true
+}
+
+func contains(xs []int64, v int64) bool {
+	for _, x := range xs {
+		if x == v {
+			return true
+		}
+	}
+	return false
+}

