+package iamresolver
+
+import (
+	"cmp"
+	"context"
+	"slices"
+	"strconv"
+	"strings"
+
+	libslices "github.com/sitoo/auth/lib/slices"
+	"github.com/sitoo/auth/middleware"
+	"github.com/sitoo/auth/model"
+	"github.com/sitoo/auth/provider/iam"
+	"github.com/sitoo/go-utils-common/errors"
+	"github.com/sitoo/go-utils-common/log"
+	"github.com/sitoo/go-utils-common/system"
+	"golang.org/x/sync/errgroup"
+)
+
+type AccountID int64
+type NumSites int64
+
+type UserRolesResolver struct {
+	client    iam.Client
+	accountID int64
+	numSites  int64
+}
+
+// NewUserRolesResolver creates a new UserRolesResolver
+func NewUserRolesResolver(client iam.Client, accountID AccountID, numSites NumSites) *UserRolesResolver {
+	return &UserRolesResolver{
+		client:    client,
+		accountID: int64(accountID),
+		numSites:  int64(numSites),
+	}
+}
+
+// SolveRoles returns the user's active role slugs grouped by site.
+//
+// It fetches the user's IAM assignments for the account, loads the referenced
+// roles, keeps only active roles with backoffice or POS login permission, and
+// expands each assignment across the user's active sites. Assignments without
+// explicit sites are expanded to all sites 1..numSites. When multiple roles
+// apply to the same site, only the highest-ranked role (lowest rank value) is
+// kept. Returns Forbidden when the account has no sites configured but active
+// roles exist.
+func (u *UserRolesResolver) SolveRoles(
+	ctx context.Context,
+	userID string,
+	userSitesNotActive []int64,
+) (model.SiteRolesMap, error) {
+	if u.numSites == 0 {
+		return nil, errors.Errorf(errors.CodeForbidden, "No sites available")
+	}
+
+	iamUserRoleAssignments, err := u.fetchIAMUserRoleAssignments(ctx, userID)
+	if err != nil {
+		return nil, errors.WithMessage(err, "fetching IAM user role assignments")
+	}
+
+	roles, err := u.fetchRolesBySlugs(ctx, collectUniqueIAMSlugs(iamUserRoleAssignments))
+	if err != nil {
+		return nil, errors.WithMessage(err, "fetching roles by slugs")
+	}
+
+	return resolveActiveUserRoleSlugsPerSite(
+		iamUserRoleAssignments,
+		roles,
+		userSitesNotActive,
+		u.numSites,
+	), nil
+}
+
+// fetchIAMUserRoleAssignments fetches the user's assignment at (account).
+// Returns nil when there is no iam or legacy assignment.
+func (u *UserRolesResolver) fetchIAMUserRoleAssignments(
+	ctx context.Context,
+	userID string,
+) ([]iam.Assignment, error) {
+	auth, _ := middleware.ForwardedAuthorizationFromCtx(ctx)
+	userID = normalizeUserID(userID)
+	env, err := resolveIAMEnvironment(ctx, u.accountID)
+	if err != nil {
+		return nil, errors.WithMessage(err, "resolving IAM environment")
+	}
+	list, err := u.client.ListUserAssignments(ctx, auth, iam.ListUserAssignmentsInput{
+		UserIDs:     []string{userID},
+		Environment: env,
+		AccountID:   new(u.accountID),
+	})
+	if err != nil {
+		if e, ok := errors.AsError(err); !ok || e.Code() != errors.CodeNotFound {
+			logIAMError(ctx, "listUserRoleAssignments", u.accountID, nil, userID, err)
+			return nil, err
+		}
+	}
+	return list, nil
+}
+
+func (u *UserRolesResolver) fetchRolesBySlugs(
+	ctx context.Context,
+	slugs []string,
+) ([]iam.Role, error) {
+	const (
+		batchSize             = 20
+		maxConcurrentRequests = 4
+	)
+
+	if len(slugs) == 0 {
+		return nil, nil
+	}
+
+	auth, _ := middleware.ForwardedAuthorizationFromCtx(ctx)
+	env, err := resolveIAMEnvironment(ctx, u.accountID)
+	if err != nil {
+		return nil, errors.WithMessage(err, "resolving IAM environment")
+	}
+
+	slugBatches := libslices.Batch(slugs, batchSize)
+	batchresults := make([][]iam.Role, len(slugBatches))
+
+	g, ctx := errgroup.WithContext(ctx)
+	g.SetLimit(maxConcurrentRequests)
+
+	for i, slugBatch := range slugBatches {
+		g.Go(func() error {
+			select {
+			case <-ctx.Done():
+				return ctx.Err()
+			default:
+			}
+
+			roles, err := u.client.ListRoles(ctx, auth, iam.GetRolesInput{
+				Slugs:       slugBatch,
+				Environment: env,
+				Num:         new(int64(batchSize)),
+				Sort:        new(iam.GetRolesInputSortRank),
+			})
+			if err != nil {
+				logIAMError(ctx, "listRoles", u.accountID, nil, "", err)
+				return err
+			}
+
+			batchresults[i] = roles.Items
+			return nil
+		})
+	}
+
+	err = g.Wait()
+	if err != nil {
+		if _, ok := errors.AsError(err); !ok {
+			return nil, errors.Wrap(err, errors.CodeBadGateway, "fetching roles by slugs")
+		}
+		return nil, errors.WithMessage(err, "fetching roles by slugs")
+	}
+
+	// Sort by rank asc (lower value; higher ranked)
+	res := slices.Concat(batchresults...)
+	slices.SortFunc(res, func(a, b iam.Role) int {
+		return cmp.Compare(a.Rank, b.Rank)
+	})
+	return res, nil
+}
+
