+// logIAMError emits an iam_error log line with the operation, scope, and
+// underlying error.
+func logIAMError(ctx context.Context, op string, accountID int64, siteID *int64, userID string, err error) {
+	entry := log.Entry("iam call failed").
+		String("tag", "iam_error").
+		String("op", op).
+		String("account_id", strconv.FormatInt(accountID, 10)).
+		Error("error", err)
+	if siteID != nil {
+		entry = entry.String("site_id", strconv.FormatInt(*siteID, 10))
+	}
+	if userID != "" {
+		entry = entry.String("user_id", userID)
+	}
+	log.MustGetFromContext(ctx).LogError(entry)
+}
+
+// resolveIAMEnvironment derives the IAM API "environment" parameter
+// (sandbox|production) from the account's Sitoo system node. Only nodeID
+// 900 maps to sandbox; everything else (including node-930 = test cluster
+// and node-940 = production cluster, plus dev <=0) maps to production
+// within its own IAM cluster.
+func resolveIAMEnvironment(ctx context.Context, accountID int64) (iam.Environment, error) {
+	mgr, err := system.FromContext(ctx)
+	if err != nil {
+		return "", errors.Errorf(errors.CodeInternalServerError, "retrieve system manager from context")
+	}
+	nodeID, err := mgr.GetSystemNodeId(accountID)
+	if err != nil {
+		return "", errors.Wrapf(err, errors.CodeInternalServerError, "get node ID for system")
+	}
+	if nodeID == 900 {
+		return iam.EnvironmentSandbox, nil
+	}
+	return iam.EnvironmentProduction, nil
+}
+
+// collectUniqueIAMSlugs filters out duplicate slugs and legacy roles.
+func collectUniqueIAMSlugs(roleV2Assignments []iam.Assignment) []string {
+	slugs := []string{}
+	seen := map[string]struct{}{}
+	for _, item := range roleV2Assignments {
+		if item.Source != iam.SourceIAM {
+			continue
+		}
+
+		if _, alreadySeen := seen[item.RoleSlug]; alreadySeen {
+			continue
+		}
+
+		seen[item.RoleSlug] = struct{}{}
+		slugs = append(slugs, item.RoleSlug)
+	}
+	return slugs
+}
+
+// filterActiveIAMRolesWithLoginPermission removes roles which status is not active and don't have
+// any permissions to login to either backoffice or POS.
+func filterActiveIAMRolesWithLoginPermission(roles []iam.Role) []string {
+	var ret []string
+	for _, role := range roles {
+		if role.Status != iam.RoleStatusActive {
+			continue
+		}
+
+		if !hasAnyIAMLoginPermission(role) {
+			continue
+		}
+
+		ret = append(ret, role.Slug)
+	}
+
+	return ret
+}
+
+func hasAnyIAMLoginPermission(role iam.Role) bool {
+	hasBOLogin := false
+	hasPOSLogin := false
+	if len(role.Permissions.BO) > 0 {
+		_, hasBOLogin = role.Permissions.BO["backoffice.login"]
+	}
+	if len(role.Permissions.POS) > 0 {
+		_, hasPOSLogin = role.Permissions.POS["pos.login"]
+	}
+	return hasBOLogin || hasPOSLogin
+}
+
+func resolveActiveUserRoleSlugsPerSite(
+	assignments []iam.Assignment,
+	roles []iam.Role,
+	sitesUserInactive []int64,
+	numSites int64,
+) model.SiteRolesMap {
+	activeRoleSlugs := filterActiveIAMRolesWithLoginPermission(roles)
+	if len(activeRoleSlugs) == 0 {
+		return make(model.SiteRolesMap)
+	}
+
+	c := newSiteRolesCollector(sitesUserInactive)
+	allSiteIDs := makeSiteIDsSlice(numSites)
+
+	for _, a := range assignments {
+		if a.Source != iam.SourceIAM || !slices.Contains(activeRoleSlugs, a.RoleSlug) {
+			continue
+		}
+
+		siteIDs := a.SiteIDs
+		if len(a.SiteIDs) == 0 {
+			// The role is not constrained to a specific site
+			siteIDs = allSiteIDs
+		}
+		c.addRoleToSites(a.RoleSlug, siteIDs)
+	}
+
+	// Preserve order from activeRoleSlugs
+	return c.produceSortedRoles(activeRoleSlugs)
+}
+
+func makeSiteIDsSlice(numSites int64) []int64 {
+	if numSites < 0 {
+		return make([]int64, 0)
+	}
+
+	s := make([]int64, numSites)
+	for siteID := int64(1); siteID <= numSites; siteID++ {
+		s[siteID-1] = siteID
+	}
+	return s
+}
+
+type siteRolesCollector struct {
+	siteRoles         map[int64]map[string]struct{}
+	sitesUserInactive []int64
+}
+
+func newSiteRolesCollector(sitesUserInactive []int64) *siteRolesCollector {
+	return &siteRolesCollector{
+		siteRoles:         make(map[int64]map[string]struct{}),
+		sitesUserInactive: sitesUserInactive,
+	}
+}
+
+func (s *siteRolesCollector) addRoleToSites(roleSlug string, siteIDs []int64) {
+	for _, siteID := range siteIDs {
+		if slices.Contains(s.sitesUserInactive, siteID) {
+			return
+		}
+		if _, ok := s.siteRoles[siteID]; !ok {
+			s.siteRoles[siteID] = make(map[string]struct{})
+		}
+		s.siteRoles[siteID][roleSlug] = struct{}{}
+	}
+}
+
+func (s *siteRolesCollector) produceSortedRoles(originalRoleOrder []string) model.SiteRolesMap {
+	rolesPerSite := make(model.SiteRolesMap, len(s.siteRoles))
+	for _, slug := range originalRoleOrder {
+		for siteID, assignedSlugs := range s.siteRoles {
+			if _, ok := assignedSlugs[slug]; ok {
+				rolesPerSite[siteID] = append(rolesPerSite[siteID], slug)
+			}
+		}
+	}
+	return rolesPerSite
+}

