+func convertRolesToSitePermissions(sitesRoles model.SiteRolesMap) map[string]model.SitePermission {
+	sessionSitePermissions := make(map[string]model.SitePermission, len(sitesRoles))
+
+	for siteID, siteRoles := range sitesRoles {
+		role := model.ROLE_V2
+		for _, siteRole := range siteRoles {
+			if model.IsLegacyRole(siteRole) { // handle legacy roles coming from IAM, which is not expected
+				role = siteRole
+				break
+			}
+		}
+		sessionSitePermissions[strconv.FormatInt(siteID, 10)] = model.SitePermission{
+			UserRole: role,
+		}
+	}
+
+	return sessionSitePermissions
