+// mapUserSiteRolesToSession composes the site-role data included in the session response.
+func mapUserSiteRolesToSession(legacySiteRole model.SiteRoleMap, iamSitesRoles model.SiteRolesMap) []genmodel.SessionSiteRole {
+	ret := make([]genmodel.SessionSiteRole, 0, len(legacySiteRole)+len(iamSitesRoles))
+
+	for siteID, iamRoles := range iamSitesRoles {
+		for _, iamRole := range iamRoles {
+			ret = append(ret, genmodel.SessionSiteRole{
+				Id:     siteID,
+				Source: genmodel.SESSIONROLESOURCE_IAM,
+				Role:   iamRole,
+			})
+		}
+	}
+
+	for siteID, legacyRole := range legacySiteRole {
+		if _, overridden := iamSitesRoles[siteID]; overridden {
+			continue
+		}
+		ret = append(ret, genmodel.SessionSiteRole{
+			Id:     siteID,
+			Source: genmodel.SESSIONROLESOURCE_LEGACY,
+			Role:   legacyRole,
+		})
+	}
+
+	// Sort by SiteID ascending
+	slices.SortStableFunc(ret, func(a, b genmodel.SessionSiteRole) int {
+		return cmp.Compare(a.Id, b.Id)
+	})
+
+	return ret
+}

